import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text for display to customers.
 * All amounts are formatted using formatEuros().
 * @param {{ number?: string, customerId: string, issueDate: string, status: string, lines: Array<{ qty: number, name: string, unitPrice: number, vatRate: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : invoice.customerId;

  // Build output lines
  const lines = [];

  // First line: invoice number or DRAFT
  lines.push(invoice.number || 'DRAFT');

  // Second line: customer name
  lines.push(customerName);

  // Empty line
  lines.push('');

  // One line per invoice line
  for (const line of invoice.lines) {
    const lineTotalAmount = lineTotal(line);
    let lineStr = `${line.qty}x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(lineTotalAmount)}`;

    if (line.discountPercent) {
      const lineDiscount = Math.round((lineTotalAmount * line.discountPercent) / 100);
      lineStr += ` (${line.discountPercent}% off: -${formatEuros(lineDiscount)})`;
    }

    lines.push(lineStr);
  }

  // Empty line before totals
  lines.push('');

  // Totals
  const totals = invoiceTotals(invoice);
  if (totals.discount > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
    lines.push(`Total: ${formatEuros(totals.total)}`);
  } else {
    lines.push(`Total: ${formatEuros(totals.total)}`);
  }

  return lines.join('\n');
}

