  assert.ok(text.includes(firstCustomer.name));
  assert.ok(text.includes(products[0].name));
  assert.ok(text.includes(products[1].name));
  assert.ok(text.includes('1x'));
  assert.ok(text.includes('2x'));
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText all amounts use formatEuros', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-15',
    lines: [
      { sku: products[0].sku, qty: 5 },
    ],
  });
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  // All amounts should start with €
  const amountLines = text.split('\n').filter((l) => l.includes('@'));
  for (const line of amountLines) {
    assert.ok(line.includes('€'));
  }

  const totalLine = text.split('\n').find((l) => l.startsWith('Total:'));
  assert.ok(totalLine.includes('€'));
});

test('renderInvoiceText shows line discount', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-15',
    lines: [
      { sku: products[0].sku, qty: 1, discountPercent: 10 },
    ],
  });
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('10%'));
  assert.ok(text.includes('off'));
});

test('renderInvoiceText shows discount summary', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-15',
    lines: [
      { sku: products[0].sku, qty: 2, discountPercent: 20 },
    ],
  });
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount:'));
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText without discounts shows simple total', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-15',
    lines: [
      { sku: products[0].sku, qty: 1, discountPercent: 0 },
    ],
  });
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const totalLines = lines.filter((l) => l.includes('Total:'));
  // Should have exactly one line with "Total:"
  assert.equal(totalLines.length, 1);
  assert.ok(totalLines[0].startsWith('Total:'));
});

test('renderInvoiceText shows VAT line when VAT is present', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-15',
    lines: [
      { sku: products[0].sku, qty: 10, discountPercent: 0 },
    ],
  });
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Subtotal:'));
});

test('renderInvoiceText shows VAT before total', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-15',
    lines: [
      { sku: products[0].sku, qty: 10, discountPercent: 0 },
    ],
  });
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const vatLineIndex = lines.findIndex((l) => l.includes('VAT:'));
  const totalLineIndex = lines.findIndex((l) => l.startsWith('Total:'));

  assert.ok(vatLineIndex > -1);
  assert.ok(totalLineIndex > -1);
  assert.ok(vatLineIndex < totalLineIndex);
});

test('renderInvoiceText shows discount, VAT, and total', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-15',
    lines: [
      { sku: products[0].sku, qty: 10, discountPercent: 20 },
    ],
  });
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  const subtotalIndex = lines.findIndex((l) => l.includes('Subtotal:'));
  const discountIndex = lines.findIndex((l) => l.includes('Discount:'));
  const vatIndex = lines.findIndex((l) => l.includes('VAT:'));
  const totalIndex = lines.findIndex((l) => l.startsWith('Total:'));

  assert.ok(subtotalIndex > -1);
  assert.ok(discountIndex > -1);
  assert.ok(vatIndex > -1);
  assert.ok(totalIndex > -1);

  // Check order
  assert.ok(subtotalIndex < discountIndex);
  assert.ok(discountIndex < vatIndex);
  assert.ok(vatIndex < totalIndex);
});

